--
-- Name: integrity_monitor; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integrity_monitor (
    id bigint NOT NULL,
    monitor_type text NOT NULL,
    subject text,
    metric_name text NOT NULL,
    metric_value double precision,
    threshold_value double precision,
    passed boolean NOT NULL,
    training_window_end timestamp with time zone,
    evaluated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE integrity_monitor; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.integrity_monitor IS 'Observability-only gate-evaluation facts (e.g. ic_engine lifecycle hook decay/hold decisions). NOT authoritative state -- feature_transition_log is the sole authoritative transition record. Query-only audit trail for LIFECYCLE-06 diagnostics.';


