-- Name: memory_episodes_labeled; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.memory_episodes_labeled (
    id uuid NOT NULL,
    ts timestamp with time zone NOT NULL,
    written_at timestamp with time zone NOT NULL,
    labeled_at timestamp with time zone DEFAULT now() NOT NULL,
    kind public.memory_episode_kind NOT NULL,
    signal_id uuid NOT NULL,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    agent_id text,
    embedding public.vector(768) NOT NULL,
    embedding_text text NOT NULL,
    hmm_regime text,
    vol_regime text,
    entry_type text,
    regime_epoch integer NOT NULL,
    n_eligible integer,
    memory_assisted boolean DEFAULT false NOT NULL,
    outcome text NOT NULL,
    pnl_r double precision NOT NULL,
    mae double precision,
    mfe double precision,
    bars_in_trade integer,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_labeled_outcome CHECK ((outcome = ANY (ARRAY['never_activated'::text, 'stopped_at_entry'::text, 'stopped_in_trade'::text, 'target_1'::text, 'target_1_2'::text, 'target_full'::text, 'ttl_expired_ahead'::text, 'ttl_expired_behind'::text, 'condition_expired'::text])))
);


--
-- Name: memory_episodes_raw; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.memory_episodes_raw (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ts timestamp with time zone NOT NULL,
    written_at timestamp with time zone DEFAULT now() NOT NULL,
    kind public.memory_episode_kind NOT NULL,
    signal_id uuid,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    agent_id text,
    embedding public.vector(768),
    embedding_text text,
    hmm_regime text,
    vol_regime text,
    entry_type text,
    regime_epoch integer NOT NULL,
    n_eligible integer,
    memory_assisted boolean DEFAULT false NOT NULL,
    outcome text,
    pnl_r double precision,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT chk_raw_outcome CHECK (((outcome IS NULL) OR (outcome = ANY (ARRAY['never_activated'::text, 'stopped_at_entry'::text, 'stopped_in_trade'::text, 'target_1'::text, 'target_1_2'::text, 'target_full'::text, 'ttl_expired_ahead'::text, 'ttl_expired_behind'::text, 'condition_expired'::text]))))
);


--
-- Name: memory_regime_transitions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.memory_regime_transitions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ts_start timestamp with time zone NOT NULL,
    ts_end timestamp with time zone,
    symbol text NOT NULL,
    timeframe text NOT NULL,
    regime_epoch integer NOT NULL,
    from_regime public.memory_regime_label,
    to_regime public.memory_regime_label NOT NULL,
    duration_bars integer,
    duration_seconds double precision,
    signal_count integer,
    win_count integer,
    win_rate double precision,
    avg_pnl_r double precision,
    avg_mae double precision,
    avg_mfe double precision,
    transition_probs jsonb,
    transition_n integer,
    duration_median_bars integer,
    duration_p25_bars integer,
    duration_p75_bars integer,
    CONSTRAINT chk_transition_probs_sum CHECK (((transition_probs IS NULL) OR (abs((((((transition_probs ->> 'ranging'::text))::double precision + ((transition_probs ->> 'trending_up'::text))::double precision) + ((transition_probs ->> 'trending_down'::text))::double precision) - (1.0)::double precision)) < (0.001)::double precision))),
    CONSTRAINT chk_win_rate CHECK (((win_rate IS NULL) OR ((win_rate >= (0.0)::double precision) AND (win_rate <= (1.0)::double precision))))
);


