    plugin_regime_type text,
    garch_sigma_at_fire double precision,
    is_shadow boolean DEFAULT false NOT NULL,
    is_backfill boolean DEFAULT false NOT NULL,
    status public.signal_status_type DEFAULT 'pending'::public.signal_status_type NOT NULL,
    signal_schema_version integer,
    ttl_bars integer,
    expires_at timestamp with time zone,
    signal_computed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    feature_ts timestamp with time zone,
    concurrent_signal_count integer,
    concurrent_plugins text[]
);


--
-- Name: trade_executions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trade_executions (
    execution_id uuid NOT NULL,
    frame_id uuid NOT NULL,
    actual_fill_price double precision,
    actual_exit_price double precision,
    actual_pnl_r double precision,
    actual_mfe double precision,
    actual_mae double precision,
    actual_bars integer,
    market_entry_price double precision,
    market_entry_gap_bars integer,
    exit_reason text,
    executed_at timestamp with time zone,
    exited_at timestamp with time zone,
    regime_at_exit integer,
    outcome public.signal_outcome_type,
    CONSTRAINT chk_te_exit_reason CHECK (((exit_reason IS NULL) OR (exit_reason = ANY (ARRAY['stop_loss'::text, 'chandelier_stop'::text, 'condition_expired'::text, 'ttl_expired'::text, 'ttl_expired_ahead'::text, 'ttl_expired_behind'::text, 'target_hit'::text]))))
);


--
-- Name: trade_frames; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trade_frames (
    frame_id uuid NOT NULL,
    signal_id uuid NOT NULL,
    signal_ts timestamp with time zone NOT NULL,
    entry_type public.entry_type_type NOT NULL,
    direction text NOT NULL,
    entry_price double precision,
    stop_price double precision,
    target_price double precision,
    r_multiple double precision,
    ttl_bars integer,
    expires_at timestamp with time zone,
    counterfactual_pnl_r double precision,
    counterfactual_mfe double precision,
    counterfactual_mae double precision,
    counterfactual_bars integer,
    counterfactual_exit_reason text,
    counterfactual_measured_at timestamp with time zone,
    was_selected boolean DEFAULT false NOT NULL,
    frame_details jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    regime_at_activation integer,
    targets double precision[]
);


--
-- Name: signal_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.signal_ledger AS
 SELECT se.signal_id,
    se.ts,
    se.ts AS "timestamp",
    se.symbol,
    se.tf,
    se.tf AS timeframe,
    se.setup_plugin,
    se.direction,
    se.raw_confidence,
    se.calibrated_confidence,
    se.cis_score,
    se.factor_scores,
    se.context_features,
    se.ctf_score,
    se.ctf_confirmed,
    se.zone_friction_score,
    se.hmm_regime_at_fire,
    se.plugin_regime_type,
    se.garch_sigma_at_fire,
    se.is_shadow,
    se.is_backfill,
    se.status,
    se.signal_schema_version,
    se.ttl_bars,
    se.expires_at,
    COALESCE(se.signal_computed_at, se.ts) AS signal_computed_at,
    se.signal_computed_at AS signal_computed_at_raw,
    se.feature_ts,
    se.concurrent_signal_count,
    se.concurrent_plugins,
    ((tf.frame_details ->> 'activated_at'::text))::timestamp with time zone AS activated_at,
    ((tf.frame_details ->> 'activation_price'::text))::double precision AS activation_price,
    tf.targets,
    ((tf.frame_details ->> 'entry_zone_low'::text))::double precision AS entry_zone_low,
    ((tf.frame_details ->> 'entry_zone_high'::text))::double precision AS entry_zone_high,
    ((tf.frame_details ->> 'market_entry_price'::text))::double precision AS market_entry_price,
    ((tf.frame_details ->> 'trailing_stop_price'::text))::double precision AS trailing_stop_price,
    (tf.frame_details ->> 'chandelier_vol_source'::text) AS chandelier_vol_source,
    ((tf.frame_details ->> 'mae'::text))::double precision AS mae,
    ((tf.frame_details ->> 'mfe'::text))::double precision AS mfe,
    tf.frame_id,
    tf.entry_type,
    tf.entry_price,
    tf.stop_price,
    tf.stop_price AS stop_loss,
    tf.target_price,
    tf.r_multiple,
    tf.counterfactual_pnl_r,
    tf.counterfactual_mfe,
    tf.counterfactual_mae,
    tf.counterfactual_exit_reason,
    tf.was_selected,
    tf.regime_at_activation,
    te.execution_id,
    te.actual_pnl_r,
    te.actual_fill_price,
    te.actual_exit_price,
    te.exit_reason,
    te.executed_at,
    te.exited_at,
    te.exited_at AS exit_at,
    te.regime_at_exit
   FROM ((public.signal_events se
     LEFT JOIN public.trade_frames tf ON (((tf.signal_id = se.signal_id) AND (tf.signal_ts = se.ts))))
     LEFT JOIN public.trade_executions te ON ((te.frame_id = tf.frame_id)));


--
-- Name: signal_lineage; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.signal_lineage (
    ts timestamp with time zone DEFAULT now() NOT NULL,
    signal_id uuid NOT NULL,
    event_type text NOT NULL,
    source text NOT NULL,
    dag_order smallint,
    multiplier double precision,
    metadata jsonb DEFAULT '{}'::jsonb,
    is_shadow boolean DEFAULT true,
    symbol text,
    tf text,
    CONSTRAINT signal_lineage_event_type_check CHECK ((event_type = ANY (ARRAY['transform'::text, 'agent_prediction'::text, 'lifecycle'::text])))
);


--
-- Name: TABLE signal_lineage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.signal_lineage IS 'Unified signal lineage: transforms, agent predictions, lifecycle events. Replaces alpha_multiplier_shadow + signal_transform_log.';


--
-- Name: signal_metrics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.signal_metrics (
    track text NOT NULL,
    setup_plugin text NOT NULL,
    tf text NOT NULL,
    regime_type text NOT NULL,
    window_days integer NOT NULL,
    n integer NOT NULL,
    n_outliers integer DEFAULT 0 NOT NULL,
    never_activated_pct double precision,
    win_rate double precision,
    avg_r double precision,
    std_r double precision,
    sharpe double precision,
    p_value double precision,
    avg_mae double precision,
    avg_mfe double precision,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    symbol text DEFAULT '*'::text NOT NULL,
    entry_type text DEFAULT '*'::text NOT NULL,
    skewness double precision,
    kurtosis double precision,
    min_r double precision,
    p5_r double precision,
    recovery_factor double precision,
    cvar_5 double precision
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.02');


--
-- Name: TABLE signal_metrics; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.signal_metrics IS 'Per-segment signal performance. track=zone (structural quality) or market (tradeable alpha). regime_type from hmm_regime_at_fire: 0->mean_reversion, 1/2->trend. ''all'' row = regime rollup for bootstrap phase (n<30 per regime).';


--
-- Name: signal_metrics_dq_failures; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.signal_metrics_dq_failures (
    signal_id uuid NOT NULL,
