    stop_loss double precision,
    pnl_r double precision,
    direction integer,
    hmm_regime integer,
    setup_plugin text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: signal_metrics_ic; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.signal_metrics_ic (
    setup_plugin text NOT NULL,
    tf text NOT NULL,
    regime_type text NOT NULL,
    window_days integer NOT NULL,
    n integer NOT NULL,
    ic double precision,
    p_value double precision,
    is_significant boolean,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    symbol text DEFAULT '*'::text NOT NULL
)
WITH (autovacuum_vacuum_scale_factor='0.05', autovacuum_analyze_scale_factor='0.02');


--
-- Name: TABLE signal_metrics_ic; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.signal_metrics_ic IS 'Information Coefficient: Pearson r(confidence, binary_outcome) per setup x regime x window. Measures whether confidence scores are predictive of zone outcomes (setup quality).';


